-- Disposable PostgreSQL fixture for compiling and smoke-testing the Settings migration.
-- This file must only run in the throwaway PostgreSQL service used by CI.
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
        CREATE ROLE anon NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
        CREATE ROLE authenticated NOLOGIN;
    END IF;
END;
$$;

CREATE SCHEMA auth;
CREATE TABLE auth.users (
    id uuid PRIMARY KEY,
    email text,
    raw_user_meta_data jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION auth.uid()
RETURNS uuid
LANGUAGE sql
STABLE
AS $$
    SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
GRANT USAGE ON SCHEMA auth TO PUBLIC;
GRANT EXECUTE ON FUNCTION auth.uid() TO PUBLIC;

CREATE TABLE public.worth_it_profiles (
    user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    worth_it_id bigint NOT NULL UNIQUE,
    username text,
    display_name text NOT NULL DEFAULT 'Worth It member',
    avatar_url text,
    created_at timestamptz NOT NULL DEFAULT now(),
    banner_url text,
    description text,
    last_seen_at timestamptz
);

-- Match the current production baseline: authenticated users may query the base
-- table only for their own row. Public profiles are accessed through the view.
ALTER TABLE public.worth_it_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users can view own Worth It profile"
    ON public.worth_it_profiles FOR SELECT TO authenticated
    USING (auth.uid() = user_id);
GRANT SELECT ON public.worth_it_profiles TO authenticated;

CREATE TABLE public.worth_it_follows (
    follower_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    followed_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (follower_user_id, followed_user_id),
    CHECK (follower_user_id <> followed_user_id)
);

CREATE TABLE public.worth_it_friends (
    user_low_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    user_high_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_low_id, user_high_id),
    CHECK (user_low_id < user_high_id)
);

CREATE TABLE public.worth_it_friend_requests (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_low_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    user_high_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    requester_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    recipient_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','declined','cancelled')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (user_low_id < user_high_id),
    CHECK (
        requester_user_id <> recipient_user_id
        AND ((requester_user_id = user_low_id AND recipient_user_id = user_high_id)
          OR (requester_user_id = user_high_id AND recipient_user_id = user_low_id))
    ),
    UNIQUE (user_low_id, user_high_id)
);

CREATE TABLE public.worth_it_social_notifications (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    recipient_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    actor_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    notification_type text NOT NULL CHECK (notification_type IN ('unfriended')),
    reason text,
    created_at timestamptz NOT NULL DEFAULT now(),
    read_at timestamptz,
    CHECK (recipient_user_id <> actor_user_id),
    CHECK (reason IS NULL OR char_length(reason) <= 500)
);

CREATE TABLE public.worth_it_notification_dismissals (
    user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    notification_kind text NOT NULL CHECK (notification_kind IN ('friend_request')),
    notification_id text NOT NULL,
    dismissed_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, notification_kind, notification_id)
);

CREATE TABLE public.worth_it_chat_conversations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_type text NOT NULL CHECK (conversation_type IN ('global','direct','group')),
    title text,
    created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
    invite_token text,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.worth_it_chat_members (
    conversation_id uuid NOT NULL REFERENCES public.worth_it_chat_conversations(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    joined_at timestamptz NOT NULL DEFAULT now(),
    last_read_at timestamptz,
    PRIMARY KEY (conversation_id, user_id)
);

CREATE TABLE public.worth_it_chat_messages (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conversation_id uuid NOT NULL REFERENCES public.worth_it_chat_conversations(id) ON DELETE CASCADE,
    sender_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    body text NOT NULL DEFAULT '',
    media_url text,
    media_type text CHECK (media_type IS NULL OR media_type IN ('image','gif')),
    filtered_reason text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (char_length(body) <= 500),
    CHECK (char_length(btrim(body)) > 0 OR media_url IS NOT NULL)
);

CREATE TABLE public.worth_it_chat_notification_preferences (
    user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    chat_key text NOT NULL,
    notifications_enabled boolean NOT NULL DEFAULT true,
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, chat_key)
);

