-- Simulate the existing view's column order. The migration may only append its
-- new show_online_status column to this established eight-column view.
CREATE VIEW public.worth_it_public_profiles AS
SELECT
    worth_it_id,
    username,
    coalesce(display_name, username, 'Worth It member') AS display_name,
    avatar_url,
    created_at,
    banner_url,
    description,
    last_seen_at
FROM public.worth_it_profiles;
GRANT SELECT ON public.worth_it_public_profiles TO anon, authenticated;

